#include <cstdio>
#include <queue>
#include <vector>
#include <cmath>
#define INF 500000000
using namespace std;

typedef pair<int,int> P;

int main() {
    int n, m, k;
    scanf("%d %d %d", &n, &m, &k);
    vector<int> l(m), a(m), b(m);
    vector<vector<P>> g(n);
    vector<int> d(n, INF), s(k);

    // Optimized input handling for edges
    for(int i = 0; i < m; i++) {
        scanf("%d %d %d", &a[i], &b[i], &l[i]);
        a[i]--; b[i]--; // Convert to 0-based indexing
        g[a[i]].emplace_back(l[i], b[i]); // Use emplace_back for efficiency
        g[b[i]].emplace_back(l[i], a[i]);
    }

    // Optimized input handling for sources
    for(int i = 0; i < k; i++) {
        scanf("%d", &s[i]);
        s[i]--; // Convert to 0-based indexing
    }

    priority_queue<P, vector<P>, greater<P>> q;
    for(int i = 0; i < k; i++) {
        d[s[i]] = 0;
        q.emplace(0, s[i]); // Use emplace for efficiency
    }

    while(!q.empty()) {
        P p = q.top(); q.pop();
        int cost = p.first, pos = p.second;
        for(const auto& edge : g[pos]) {
            int dis = cost + edge.first;
            int next = edge.second;
            if(dis < d[next]) {
                d[next] = dis;
                q.emplace(dis, next); // Use emplace for efficiency
            }
        }
    }

    double ans = 0.0;
    for(int i = 0; i < m; i++) {
        if(fabs(d[a[i]] - d[b[i]]) >= l[i]) {
            ans = max(ans, (double)max(d[a[i]], d[b[i]]));
        } else {
            ans = max(ans, (double)(l[i] + d[a[i]] + d[b[i]]) / 2);
        }
    }
    printf("%d\n", (int)(ans + 1e-9 + 0.5));
}

