#include <cstdio>
#include <queue>
#include <vector>
#include <cmath>
#define INF 500000000
using namespace std;

typedef pair<int,int> P;

int main() {
    int n, m, k;
    scanf("%d %d %d", &n, &m, &k); // Read number of nodes, edges, and sources
    vector<int> l(m), a(m), b(m); // Edge lengths and endpoints
    vector<vector<P>> g(n); // Graph representation
    vector<int> d(n, INF), s(k); // Distances and sources

    for(int i=0; i<m; i++) {
        scanf("%d %d %d", &a[i], &b[i], &l[i]); // Input edges
        a[i]--; b[i]--; // Convert to 0-based indexing
        g[a[i]].push_back(P(l[i], b[i])); // Add edge to graph
        g[b[i]].push_back(P(l[i], a[i])); // Add reverse edge
    }

    for(int i=0; i<k; i++) {
        scanf("%d", &s[i]); // Input sources
        s[i]--; // Convert to 0-based indexing
    }

    priority_queue<P, vector<P>, greater<P>> q; // Min-heap for Dijkstra's algorithm
    for(int i=0; i<k; i++) {
        d[s[i]] = 0; // Initialize distances for sources
        q.push(P(0, s[i])); // Push sources into priority queue
    }

    double ans = 0.0; // Result variable
    while(!q.empty()) {
        P p = q.top(); q.pop(); // Get the minimum distance node
        int cost = p.first, pos = p.second;
        for(const auto& edge : g[pos]) {
            int dis = cost + edge.first; // Calculate distance to next node
            int next = edge.second;
            if(dis < d[next]) {
                d[next] = dis; // Update distance if smaller
                q.push(P(dis, next)); // Push new distance to queue
            }
        }
    }

    for(int i=0; i<m; i++) {
        if(fabs(d[a[i]] - d[b[i]]) >= l[i]) {
            ans = max(ans, (double)max(d[a[i]], d[b[i]])); // Update answer
        } else {
            ans = max(ans, (double)(l[i] + d[a[i]] + d[b[i]]) / 2); // Calculate average
        }
    }
    printf("%d\n", (int)(ans + 1e-9 + 0.5)); // Print final answer
}

